import{_ as d,c as e,o as a,b0 as o}from"./chunks/framework.C5ev1SXp.js";const s="/scm-docs/assets/size-to-memory-flow.DU0077xJ.svg",i="/scm-docs/assets/load-exec-region.194LFRPN.svg",c="data:image/svg+xml;base64,",n="data:image/svg+xml;base64,",u=JSON.parse('{"title":"LV070-工程占用与分区余量实测","description":null,"frontmatter":{"title":"LV070-工程占用与分区余量实测","date":"2026-10-30T16:05:58.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/online-upgrade/iap/126d638168ae243bed6002fe","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-30T16:05:58.579Z","fulluuid":"bed6002fe12e41cd9b49d33b465eb03f","useduuid":"bed6002fe"}},"headers":[],"relativePath":"sdoc/online-upgrade/iap/126d638168ae243bed6002fe.md","filePath":"sdoc/70-在线升级/01-IAP/LV070-工程占用与分区余量实测.md","lastUpdated":1794036996000}'),r={name:"sdoc/online-upgrade/iap/126d638168ae243bed6002fe.md"};function l(p,t,h,I,g,b){return a(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="lv070-工程占用与分区余量实测" tabindex="-1">LV070-工程占用与分区余量实测 <a class="header-anchor" href="#lv070-工程占用与分区余量实测" aria-label="Permalink to &quot;LV070-工程占用与分区余量实测&quot;">​</a></h1><p>分区图画得对不对，最终要看编译器和链接器吐出来的数字。这篇先讲<strong>怎么读这些数字</strong>——<code>Program Size</code> 的四个字段落在哪、<code>.map</code> 的区域行怎么对、链接配置里哪一行才真正决定分区、余量与临界点怎么算；再用本工程在某个版本上的实测数据走一遍完整实例。方法长期有效，数字只代表那一刻。</p><h2 id="一、-先说清楚数据的时效性" tabindex="-1">一、 先说清楚数据的时效性 <a class="header-anchor" href="#一、-先说清楚数据的时效性" aria-label="Permalink to &quot;一、 先说清楚数据的时效性&quot;">​</a></h2><p>【<strong>注意</strong>】</p><p>本文第三节之后的实例数字，都是<strong>某一次构建的快照</strong>：<code>atk-f103</code> 与 <code>flash-app</code> 两个工程在 <strong>2026-10-14</strong> 做的一次全量重建。它们的作用是<strong>帮助理解布局与用量</strong>，不是长期有效的绝对指标。</p><p>（1）<strong>代码一改，数字就变</strong>。加一个模块、删一段 lwIP 功能、调整一个缓冲大小，<code>Code</code> / <code>ZI-data</code> 都会跟着动，余量表随之失效；分区上限没变时不会报错，只是余量悄悄变少。</p><p>（2）<strong>分区方案本身也会变</strong>。实例对应的方案是&quot;按 128 KB 切四块&quot;，此前用过&quot;64 KB + 448 KB&quot;。同一篇文章里的分区表只描述它对应的那一版。</p><p>（3）<strong>真正长期有效的是第二节的方法</strong>。知道怎么从 <code>Program Size</code>、<code>.map</code>、链接配置里把数字读出来、怎么交叉验证、怎么算余量，换一版代码或换一颗芯片都能重做一遍；记住某个具体的 59212 则毫无意义。</p><p>（4）<strong>复核成本很低</strong>。全量重建一次，再看一眼编译输出与 <code>.map</code> 即可，步骤见第四节。凡是拿不准&quot;现在还剩多少&quot;的时候，都应该重新量一次，而不是翻旧表。</p><h2 id="二、-通用方法" tabindex="-1">二、 通用方法 <a class="header-anchor" href="#二、-通用方法" aria-label="Permalink to &quot;二、 通用方法&quot;">​</a></h2><h3 id="_1-四个必看的数据源" tabindex="-1">1. 四个必看的数据源 <a class="header-anchor" href="#_1-四个必看的数据源" aria-label="Permalink to &quot;1. 四个必看的数据源&quot;">​</a></h3><p>判断占用不能只看一个数字，这四类来源要一起看：</p><table tabindex="0"><thead><tr><th>来源</th><th>提供什么</th><th>权威性</th></tr></thead><tbody><tr><td>编译器输出的 <code>Program Size</code></td><td>镜像总量与 RAM 总量</td><td>最高，链接器最终账目</td></tr><tr><td><code>.map</code> 的 <code>Load Region</code> / <code>Execution Region</code> 行</td><td>每个区域的基址、实际占用、上限</td><td>最高，与产物一一对应</td></tr><tr><td><code>.map</code> 的 <code>Memory Map</code> / <code>Image component sizes</code></td><td>逐段落点、各目标文件的贡献</td><td>高，可下钻到符号与文件</td></tr><tr><td>链接配置（Keil 的 <code>OCR_RVCT4</code>、GCC 的 <code>.ld</code>）</td><td>链接期生效的地址与上限</td><td>高，决定分区</td></tr></tbody></table><h3 id="_2-program-size-的四个字段" tabindex="-1">2. Program Size 的四个字段 <a class="header-anchor" href="#_2-program-size-的四个字段" aria-label="Permalink to &quot;2. Program Size 的四个字段&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Program Size: Code=6224 RO-data=448 RW-data=100 ZI-data=2108</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这四个字段的归属是固定的，弄清楚才不会把十几万字节误当成内部 RAM 占用：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th><th>是否进镜像</th><th>落在哪</th></tr></thead><tbody><tr><td><code>Code</code></td><td>指令 <code>.text</code></td><td>是</td><td>Flash</td></tr><tr><td><code>RO-data</code></td><td>只读常量：<code>const</code> 数组、字符串字面量、跳转表</td><td>是</td><td>Flash</td></tr><tr><td><code>RW-data</code></td><td>已初始化全局/静态变量 <code>.data</code></td><td>是（存初值）</td><td>Flash 存一份 + RAM 驻留一份</td></tr><tr><td><code>ZI-data</code></td><td>零初始化变量 <code>.bss</code></td><td><strong>否</strong></td><td>只在 RAM</td></tr></tbody></table><h3 id="_3-两个加权和" tabindex="-1">3. 两个加权和 <a class="header-anchor" href="#_3-两个加权和" aria-label="Permalink to &quot;3. 两个加权和&quot;">​</a></h3><p>真正要比较的是下面两个和，两者都不是&quot;四个相加&quot;：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Flash 占用 = Code + RO-data + RW-data</span></span>
<span class="line"><span>RAM  占用 = RW-data + (ZI-data 中位于片上 RAM 的部分)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><img src="`+s+'" alt="Program Size 四个字段最终落在哪"></p><p><code>ZI-data</code> 之所以不能直接和 64 KB 比，是因为它可能包含落到<strong>外部 SRAM</strong> 的绝对定位段（见第 5 小节）。此时 <code>ZI-data</code> 会虚高得离谱，直接拿它判断&quot;内部 RAM 快满了&quot;会得出完全错误的结论。</p><h3 id="_4-一条快速的判断顺序" tabindex="-1">4. 一条快速的判断顺序 <a class="header-anchor" href="#_4-一条快速的判断顺序" aria-label="Permalink to &quot;4. 一条快速的判断顺序&quot;">​</a></h3><p>拿到一次构建结果，按这个顺序看：</p><ol><li>先看 <code>Program Size</code>，算出 Flash 与 RAM 两个加权和；</li><li>再看 <code>.map</code> 的 <code>LR_IROM1.Size</code> 与 <code>ER_RW_IRAM1.Size</code>，与上一步互相验证；</li><li>两个数各自与分区上限比，得到余量与占比；</li><li>若 <code>ZI-data</code> 明显大于 <code>ER_RW_IRAM1.Size</code>，去 <code>.map</code> 里找是不是有段落到了外部内存。</li></ol><h3 id="_5-怎么读-map" tabindex="-1">5. 怎么读 <code>.map</code> <a class="header-anchor" href="#_5-怎么读-map" aria-label="Permalink to &quot;5. 怎么读 `.map`&quot;">​</a></h3><h4 id="_5-1-load-region-与-execution-region" tabindex="-1">5.1 Load Region 与 Execution Region <a class="header-anchor" href="#_5-1-load-region-与-execution-region" aria-label="Permalink to &quot;5.1 Load Region 与 Execution Region&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Load Region LR_IROM1 (Base: 0x08020000, Size: 0x00001a74, Max: 0x00020000, ABSOLUTE)</span></span>\n<span class="line"><span>  Execution Region ER_IROM1 (Exec base: 0x08020000, Load base: 0x08020000, Size: 0x00001a10, Max: 0x00020000, ABSOLUTE)</span></span>\n<span class="line"><span>  Execution Region RW_IRAM1 (Exec base: 0x20000000, Load base: 0x08021a10, Size: 0x000008a0, Max: 0x00010000, ABSOLUTE)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>四个字段的含义：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>Base</code></td><td>区域起始地址</td></tr><tr><td><code>Size</code></td><td>实际占用字节数</td></tr><tr><td><code>Max</code></td><td>链接配置里声明的上限，<strong>这就是分区边界</strong></td></tr><tr><td><code>Load base</code></td><td>该区域初值在镜像里的存放地址</td></tr></tbody></table><p><code>Load Region</code> 是&quot;装进 Flash 的那一份&quot;，<code>Execution Region</code> 是&quot;运行时落在哪&quot;。一个 <code>Load Region</code> 可以带多个执行区：代码落在 Flash，<code>.data</code> 的初值跟着镜像走，一旦跑起来就要拷进 RAM。</p><p><img src="'+i+`" alt="Load Region 与 Execution Region 的关系"></p><h4 id="_5-2-四处对应关系" tabindex="-1">5.2 四处对应关系 <a class="header-anchor" href="#_5-2-四处对应关系" aria-label="Permalink to &quot;5.2 四处对应关系&quot;">​</a></h4><p>拿 <code>Program Size</code> 去对 <code>.map</code>，有四处应当严丝合缝：</p><table tabindex="0"><thead><tr><th>对照项</th><th>应当等于</th></tr></thead><tbody><tr><td><code>Max</code>（IROM1 上的那个）</td><td>链接配置里的 <code>Size</code>，也就是分区大小</td></tr><tr><td><code>LR_IROM1.Size</code></td><td><code>Code + RO-data + RW-data</code>，即镜像大小</td></tr><tr><td><code>LR - ER_IROM1</code></td><td><code>RW-data</code>，即启动时要拷进 RAM 的 <code>.data</code></td></tr><tr><td><code>ER_RW_IRAM1.Size</code></td><td><code>RW-data + 片上 ZI</code></td></tr></tbody></table><p>装载区比执行区大出的那一小段，恰好就是&quot;镜像里存一份、启动时拷进 RAM&quot;的 <code>.data</code>。这四项能对上，说明 <code>Program Size</code> 与 <code>.map</code> 取自<strong>同一次构建</strong>；对不上，多半是拿了增量构建的旧数据。</p><h4 id="_5-3-total-rom-size-与-compressed" tabindex="-1">5.3 Total ROM Size 与 COMPRESSED <a class="header-anchor" href="#_5-3-total-rom-size-与-compressed" aria-label="Permalink to &quot;5.3 Total ROM Size 与 COMPRESSED&quot;">​</a></h4><p><code>.map</code> 末尾的 <code>Total ROM Size (Code + RO Data + RW Data)</code> 往往比 <code>LR_IROM1.Size</code> 略小，差值来自&quot;初值全为 0 的 <code>RW-data</code>&quot;——链接器把它们归进 ZI，不必在 Flash 里存初值。行尾的 <code>COMPRESSED[...]</code> 才是真正写进 hex 的字节数。</p><p>所以：</p><ul><li>判断<strong>有没有超过分区上限</strong>，看 <code>LR_IROM1.Size</code>；</li><li>判断<strong>hex 里到底写了多少字节</strong>，看 <code>Total ROM Size</code> 或 <code>COMPRESSED</code>。</li></ul><h4 id="_5-4-uninit-与绝对定位段" tabindex="-1">5.4 UNINIT 与绝对定位段 <a class="header-anchor" href="#_5-4-uninit-与绝对定位段" aria-label="Permalink to &quot;5.4 UNINIT 与绝对定位段&quot;">​</a></h4><p>落到外部内存的段通常长这样：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Load Region LR$$.ARM.__AT_0x68000000 (Base: 0x68000000, Size: 0x00000000, Max: 0x00020000, ABSOLUTE)</span></span>
<span class="line"><span>  Execution Region ER$$.ARM.__AT_0x68000000 (Exec base: 0x68000000, Size: 0x00020000, Max: 0x00020000, ABSOLUTE, UNINIT)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>两个特征：<code>Load Region</code> 的 <code>Size</code> 是 <strong>0</strong>（不占镜像任何字节），执行区带 <strong><code>UNINIT</code></strong>（C 启动代码不会去清零它）。</p><p><code>UNINIT</code> 是这类内存能用的前提：如果它是普通 ZI 区，<code>__main</code> 会在外部总线初始化之前就往那个地址写数据，结果要么总线错误，要么数据写丢。<strong>用绝对定位挂外部内存时，务必确认这一项</strong>。</p><h4 id="_5-5-组件表怎么用" tabindex="-1">5.5 组件表怎么用 <a class="header-anchor" href="#_5-5-组件表怎么用" aria-label="Permalink to &quot;5.5 组件表怎么用&quot;">​</a></h4><p><code>Image component sizes</code> 按目标文件列出 <code>Code</code> / <code>RO Data</code> / <code>RW Data</code> / <code>ZI Data</code>。它适合回答&quot;是谁占的&quot;，但有三点要注意：</p><p>（1）<strong>各行相加不等于总量</strong>。库成员、生成项（向量表、跳转表）与对齐填充另计，通常差几百到几千字节。</p><p>（2）<strong><code>inc.data</code> 不要重复计入</strong>。它表示该文件的内联数据被合进了别人的 <code>Code</code>，不是独立的占用。</p><p>（3）<strong>看排名而不是看全部</strong>。前十几名通常占总量的九成，剩下的杂项没有分析价值。</p><h3 id="_6-产物文件大小不能当占用" tabindex="-1">6. 产物文件大小不能当占用 <a class="header-anchor" href="#_6-产物文件大小不能当占用" aria-label="Permalink to &quot;6. 产物文件大小不能当占用&quot;">​</a></h3><p>同一个工程会产出好几个文件，只有一个能用来判断占用：</p><table tabindex="0"><thead><tr><th>文件</th><th>能否判断占用</th><th>原因</th></tr></thead><tbody><tr><td><code>.axf</code> / <code>.elf</code></td><td><strong>不能</strong></td><td>含调试信息，体积与代码无关，动辄是镜像的几十倍</td></tr><tr><td><code>.hex</code></td><td><strong>不能</strong></td><td>ASCII 十六进制文本，长度取决于地址跨度与换行密度</td></tr><tr><td><code>.bin</code></td><td><strong>能</strong></td><td>纯二进制，大小等于 <code>LR_IROM1.Size</code></td></tr><tr><td>帧文件（如 <code>.img</code>）</td><td>能，但要减去帧开销</td><td>bin + 头部 + 尾部魔数</td></tr></tbody></table><p><code>.bin</code> 与 <code>LR_IROM1.Size</code> 相等是一条很好用的自检：如果两者差了几十上百字节，说明 <code>.bin</code> 是上一次构建留下的。</p><p>帧文件那条同样值得记住：<code>镜像 + 帧开销 = 帧文件</code>，帧开销是定值（本工程 16 字节头 + 8 字节尾 = 24 字节）。用这个差可以粗判&quot;上位机打包有没有多加东西&quot;。</p><h3 id="_7-链接配置与分区边界" tabindex="-1">7. 链接配置与分区边界 <a class="header-anchor" href="#_7-链接配置与分区边界" aria-label="Permalink to &quot;7. 链接配置与分区边界&quot;">​</a></h3><h4 id="_7-1-只认真正参与链接的那一行" tabindex="-1">7.1 只认真正参与链接的那一行 <a class="header-anchor" href="#_7-1-只认真正参与链接的那一行" aria-label="Permalink to &quot;7.1 只认真正参与链接的那一行&quot;">​</a></h4><p>Keil 工程的 <code>&lt;umfTarg&gt;1</code>（Use Memory Layout from Target Dialog）+ 空 scatter 文件，意味着<strong>唯一生效的布局来源是 <code>.uvprojx</code> 里的 <code>OCR_RVCT4</code></strong>：</p><div class="language-xml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">OCR_RVCT4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">StartAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;0x8020000&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">StartAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;0x20000&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">OCR_RVCT4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>GCC 工具链同理，看 <code>.ld</code> 里的 <code>FLASH (rx) : ORIGIN = ..., LENGTH = ...</code>。</p><h4 id="_7-2-别把芯片描述当分区" tabindex="-1">7.2 别把芯片描述当分区 <a class="header-anchor" href="#_7-2-别把芯片描述当分区" aria-label="Permalink to &quot;7.2 别把芯片描述当分区&quot;">​</a></h4><p><code>.uvprojx</code> 里还有一组 <code>OnChipMemories/IROM</code>，那是<strong>芯片物理 ROM 的描述</strong>，通常写着整片大小，与链接无关。判断分区时看它，会得出&quot;两个工程都从 <code>0x08000000</code> 起&quot;这种完全错误的结论。</p><p>验证方法很直接：去 <code>.map</code> 里看 <code>LR_IROM1</code> 的 <code>Base</code> 和 <code>Max</code>，那才是链接期真正用的值。</p><h4 id="_7-3-把上限压到分区大小" tabindex="-1">7.3 把上限压到分区大小 <a class="header-anchor" href="#_7-3-把上限压到分区大小" aria-label="Permalink to &quot;7.3 把上限压到分区大小&quot;">​</a></h4><p>分区能否被&quot;守住&quot;，取决于有没有人把 <code>Size</code> 设成<strong>自己那块的大小</strong>，而不是整片大小：</p><ul><li>设成整片：谁都可以长到别人的地盘，链接器一路放行，故障延迟到运行时甚至下一次升级才爆发；</li><li>设成分区大小：长过界当场报 <code>L6220E: Execution Region ... exceeds maximum size</code>，问题在编译阶段就暴露。</li></ul><p><img src="`+c+`" alt="链接上限设成整片还是设成自己那块"></p><p>这条防线可以自己验证：把 <code>Size</code> 临时改成明显偏小的值重建一次，应当看到上面那行报错；改回原值即恢复。</p><h4 id="_7-4-页对齐" tabindex="-1">7.4 页对齐 <a class="header-anchor" href="#_7-4-页对齐" aria-label="Permalink to &quot;7.4 页对齐&quot;">​</a></h4><p>Flash 的擦除单位是页（STM32F103 大容量型号 2 KB），所以分区的起始地址和结束边界都必须落在页边界上，否则擦除 App 区时会连带擦掉相邻分区的数据。等价地说，起始地址必须能被页大小整除，分区大小也必须是页大小的整数倍。</p><h3 id="_8-余量、临界点与经验阈值" tabindex="-1">8. 余量、临界点与经验阈值 <a class="header-anchor" href="#_8-余量、临界点与经验阈值" aria-label="Permalink to &quot;8. 余量、临界点与经验阈值&quot;">​</a></h3><h4 id="_8-1-余量与占比" tabindex="-1">8.1 余量与占比 <a class="header-anchor" href="#_8-1-余量与占比" aria-label="Permalink to &quot;8.1 余量与占比&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>余量 = 分区上限 - 实际占用</span></span>
<span class="line"><span>占比 = 实际占用 / 分区上限</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>两个都要报：只看余量，128 KB 的 20 KB 与 512 KB 的 20 KB 完全不是一回事；只看占比，小分区里 3 KB 差距也会被放大成&quot;很危险&quot;。</p><h4 id="_8-2-扩容临界点" tabindex="-1">8.2 扩容临界点 <a class="header-anchor" href="#_8-2-扩容临界点" aria-label="Permalink to &quot;8.2 扩容临界点&quot;">​</a></h4><p>即&quot;还差多少字节就会撞线&quot;：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>临界增量 = 分区上限 - LR_IROM1.Size</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>对 Bootloader 这类<strong>运行时不可替换</strong>的组件，这个数要额外留出余量——它长过界的后果是设备再也收不到新固件（见第三节第 4 小节）。</p><h4 id="_8-3-多少算够" tabindex="-1">8.3 多少算够 <a class="header-anchor" href="#_8-3-多少算够" aria-label="Permalink to &quot;8.3 多少算够&quot;">​</a></h4><p>没有统一标准，但有几条经验线可以参考：</p><table tabindex="0"><thead><tr><th>场景</th><th>建议余量</th></tr></thead><tbody><tr><td>仍在频繁加功能的模块</td><td>不少于当前占用的 50%</td></tr><tr><td>稳定模块（Bootloader 这类）</td><td>不少于 20%，并保证&quot;再塞一个中等模块也够&quot;</td></tr><tr><td>一次性验证工程</td><td>只要不撞线即可</td></tr></tbody></table><h3 id="_9-烧写耗时怎么估" tabindex="-1">9. 烧写耗时怎么估 <a class="header-anchor" href="#_9-烧写耗时怎么估" aria-label="Permalink to &quot;9. 烧写耗时怎么估&quot;">​</a></h3><p>不需要实测也能算出量级：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>耗时 ≈ 擦除页数 × 单页擦除时间 + 写入次数 × 单次编程时间</span></span>
<span class="line"><span>写入次数 = 镜像字节数 / 编程粒度</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>代入手册典型值（2 KB 页擦除约 20 ms、半字编程约 50 µs）就能得到下限；实际受 <code>HAL_FLASH_Program</code> 的逐半字循环开销影响，通常比估算值高一截，所以结论要说成&quot;约多少、最坏多少&quot;。</p><p>【<strong>注意</strong>】</p><p>耗时估算的用途不是精确预测，而是判断&quot;这段时间里别的东西会不会崩&quot;：串口会不会溢出、看门狗会不会复位、网络心跳会不会超时。这三个问题的答案都在&quot;秒&quot;这个量级上，粗估完全够用。</p><h2 id="三、-实例-2026-10-14-全量重建" tabindex="-1">三、 实例（2026-10-14 全量重建） <a class="header-anchor" href="#三、-实例-2026-10-14-全量重建" aria-label="Permalink to &quot;三、 实例（2026-10-14 全量重建）&quot;">​</a></h2><h3 id="_1-芯片资源与分区" tabindex="-1">1. 芯片资源与分区 <a class="header-anchor" href="#_1-芯片资源与分区" aria-label="Permalink to &quot;1. 芯片资源与分区&quot;">​</a></h3><h4 id="_1-1-两个工程" tabindex="-1">1.1 两个工程 <a class="header-anchor" href="#_1-1-两个工程" aria-label="Permalink to &quot;1.1 两个工程&quot;">​</a></h4><table tabindex="0"><thead><tr><th>工程</th><th>路径</th><th>角色</th><th>产物</th></tr></thead><tbody><tr><td><code>atk-f103</code></td><td><code>atk-f103/Core/Src/main.c</code></td><td>Bootloader：收帧、校验、烧写、跳转</td><td><code>atk-f103.axf</code> / <code>.hex</code></td></tr><tr><td><code>flash-app</code></td><td><code>flash-app/Core/Src/main.c</code></td><td>App：被升级的目标程序</td><td><code>flash-app.bin</code> / <code>app.img</code></td></tr></tbody></table><h4 id="_1-2-三块存储资源" tabindex="-1">1.2 三块存储资源 <a class="header-anchor" href="#_1-2-三块存储资源" aria-label="Permalink to &quot;1.2 三块存储资源&quot;">​</a></h4><p>器件是 STM32F103ZET6：</p><table tabindex="0"><thead><tr><th>资源</th><th>地址范围</th><th>容量</th><th>本工程用途</th></tr></thead><tbody><tr><td>内部 Flash</td><td><code>0x08000000 ~ 0x0807FFFF</code></td><td>512 KB</td><td>Bootloader 代码 + App 镜像 + 两块预留</td></tr><tr><td>内部 SRAM</td><td><code>0x20000000 ~ 0x2000FFFF</code></td><td>64 KB</td><td>栈、堆、全局变量</td></tr><tr><td>外部 SRAM</td><td><code>0x68000000 ~ 0x680FFFFF</code></td><td>1 MB</td><td>IAP 载荷缓冲（FSMC Bank1 NOR/SRAM3）</td></tr></tbody></table><h4 id="_1-3-128-kb-四等分与页对齐" tabindex="-1">1.3 128 KB 四等分与页对齐 <a class="header-anchor" href="#_1-3-128-kb-四等分与页对齐" aria-label="Permalink to &quot;1.3 128 KB 四等分与页对齐&quot;">​</a></h4><p>内部 Flash 按 <strong>128 KB 均分四块</strong>，每块用一个工程的链接上限来约束：</p><table tabindex="0"><thead><tr><th>块</th><th>地址范围</th><th>页号</th><th>用途</th><th>链接上限</th></tr></thead><tbody><tr><td>第 1 块</td><td><code>0x08000000 ~ 0x0801FFFF</code></td><td>0 ~ 63</td><td>Bootloader（<code>atk-f103</code>）</td><td><code>0x20000</code> = 128 KB</td></tr><tr><td>第 2 块</td><td><code>0x08020000 ~ 0x0803FFFF</code></td><td>64 ~ 127</td><td>App（<code>flash-app</code>）</td><td><code>0x20000</code> = 128 KB</td></tr><tr><td>第 3 块</td><td><code>0x08040000 ~ 0x0805FFFF</code></td><td>128 ~ 191</td><td>预留，暂未分配</td><td>—</td></tr><tr><td>第 4 块</td><td><code>0x08060000 ~ 0x0807FFFF</code></td><td>192 ~ 255</td><td>预留，暂未分配</td><td>—</td></tr></tbody></table><p>这样切的好处是<strong>四块彼此独立</strong>：将来谁要扩容就动自己那块的上限，不必像&quot;两块相加恒等于 512 KB&quot;那样互相挤（这正是上一版 64 KB + 448 KB 方案最别扭的地方）。</p><p>Flash 的擦除单位是 <strong>2 KB 一页</strong>，512 KB 共 256 页：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// atk-f103/Drivers/BSP/Iap/iap.c</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* STM32F103ZET6 是大容量型号, 内部 Flash 按 2KB 分页 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IAP_FLASH_PAGE_SIZE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     2048</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>0x08020000</code> 正好是第 64 页的起点（<code>(0x08020000 - 0x08000000) ÷ 0x800 = 64</code>），第 1 块与第 2 块的分界天然满足擦除粒度要求。</p><h4 id="_1-4-两个工程的链接配置" tabindex="-1">1.4 两个工程的链接配置 <a class="header-anchor" href="#_1-4-两个工程的链接配置" aria-label="Permalink to &quot;1.4 两个工程的链接配置&quot;">​</a></h4><table tabindex="0"><thead><tr><th>工程</th><th>IROM1 起始</th><th>IROM1 大小</th><th>声明覆盖范围</th><th>IRAM1</th></tr></thead><tbody><tr><td><code>atk-f103</code></td><td><code>0x08000000</code></td><td><code>0x20000</code> = 128 KB</td><td><code>0x08000000 ~ 0x0801FFFF</code></td><td><code>0x20000000 / 0x10000</code></td></tr><tr><td><code>flash-app</code></td><td><code>0x08020000</code></td><td><code>0x20000</code> = 128 KB</td><td><code>0x08020000 ~ 0x0803FFFF</code></td><td><code>0x20000000 / 0x10000</code></td></tr></tbody></table><p>两个 IROM1 各占一块，互不重叠；第 3、4 块目前没有任何工程声明，处于完全空白状态。</p><h3 id="_2-bootloader-与-app-的实测占用" tabindex="-1">2. Bootloader 与 App 的实测占用 <a class="header-anchor" href="#_2-bootloader-与-app-的实测占用" aria-label="Permalink to &quot;2. Bootloader 与 App 的实测占用&quot;">​</a></h3><h4 id="_2-1-program-size-原文" tabindex="-1">2.1 Program Size 原文 <a class="header-anchor" href="#_2-1-program-size-原文" aria-label="Permalink to &quot;2.1 Program Size 原文&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bootloader(atk-f103): Program Size: Code=56472 RO-data=2204 RW-data=536 ZI-data=153928</span></span>
<span class="line"><span>                      &quot;atk-f103\\atk-f103.axf&quot; - 0 Error(s), 0 Warning(s).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>flash-app:           Program Size: Code=6224 RO-data=448 RW-data=100 ZI-data=2108</span></span>
<span class="line"><span>                      &quot;flash-app\\flash-app.axf&quot; - 0 Error(s), 0 Warning(s).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="_2-2-代入两个加权和" tabindex="-1">2.2 代入两个加权和 <a class="header-anchor" href="#_2-2-代入两个加权和" aria-label="Permalink to &quot;2.2 代入两个加权和&quot;">​</a></h4><table tabindex="0"><thead><tr><th>工程</th><th>Code</th><th>RO-data</th><th>RW-data</th><th>ZI-data</th><th><strong>Flash 合计</strong></th><th><strong>内部 RAM</strong></th><th>外部 SRAM</th></tr></thead><tbody><tr><td><code>atk-f103</code></td><td>56472</td><td>2204</td><td>536</td><td>153928</td><td><strong>59212 B</strong>（0xE74C）</td><td><strong>23392 B</strong>（0x5B60）</td><td>131072 B</td></tr><tr><td><code>flash-app</code></td><td>6224</td><td>448</td><td>100</td><td>2108</td><td><strong>6772 B</strong>（0x1A74）</td><td><strong>2208 B</strong>（0x8A0）</td><td>0</td></tr></tbody></table><p>Bootloader 内部 RAM 的 23392 字节这么算出来：<code>153928 - 131072 = 22856</code>（片内 <code>.bss</code>）+ <code>536</code>（RW-data）。也就是 <code>ZI-data</code> 里 <strong>85% 在片外 SRAM</strong>（131072 字节的 IAP 载荷缓冲），剩下 22856 字节才是片内的零初始化数据。</p><p>这个 153928 如果全落在内部 RAM，早就超过 64 KB 让链接器报 <code>region overflow</code> 了——把载荷缓冲挪到片外 SRAM 这个决定，等于把&quot;链接期就不可能通过&quot;变成了&quot;链接期只占 22 KB&quot;。这正是第二节第 3 小节说的&quot;<code>ZI-data</code> 不能直接和 64 KB 比&quot;。</p><h4 id="_2-3-与-map-的交叉验证" tabindex="-1">2.3 与 <code>.map</code> 的交叉验证 <a class="header-anchor" href="#_2-3-与-map-的交叉验证" aria-label="Permalink to &quot;2.3 与 \`.map\` 的交叉验证&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>atk-f103.map:</span></span>
<span class="line"><span>  Load Region LR_IROM1 (Base: 0x08000000, Size: 0x0000e74c, Max: 0x00020000, ABSOLUTE, COMPRESSED[0x0000e54c])</span></span>
<span class="line"><span>    Execution Region ER_IROM1 (Exec base: 0x08000000, Load base: 0x08000000, Size: 0x0000e534, Max: 0x00020000, ABSOLUTE)</span></span>
<span class="line"><span>    Execution Region RW_IRAM1 (Exec base: 0x20000000, Load base: 0x0800e534, Size: 0x00005b60, Max: 0x00010000, ABSOLUTE, COMPRESSED[0x00000018])</span></span>
<span class="line"><span>  Load Region LR$$.ARM.__AT_0x68000000 (Base: 0x68000000, Size: 0x00000000, Max: 0x00020000, ABSOLUTE)</span></span>
<span class="line"><span>    Execution Region ER$$.ARM.__AT_0x68000000 (Exec base: 0x68000000, Load base: 0x68000000, Size: 0x00020000, Max: 0x00020000, ABSOLUTE, UNINIT)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>flash-app.map:</span></span>
<span class="line"><span>  Load Region LR_IROM1 (Base: 0x08020000, Size: 0x00001a74, Max: 0x00020000, ABSOLUTE)</span></span>
<span class="line"><span>    Execution Region ER_IROM1 (Exec base: 0x08020000, Load base: 0x08020000, Size: 0x00001a10, Max: 0x00020000, ABSOLUTE)</span></span>
<span class="line"><span>    Execution Region RW_IRAM1 (Exec base: 0x20000000, Load base: 0x08021a10, Size: 0x000008a0, Max: 0x00010000, ABSOLUTE)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><table tabindex="0"><thead><tr><th>对照项</th><th>Bootloader</th><th>App</th><th>说明</th></tr></thead><tbody><tr><td><code>Max</code>（两个 IROM1）</td><td><code>0x20000</code> = 128 KB</td><td><code>0x20000</code> = 128 KB</td><td>与 <code>OCR_RVCT4</code> 的 <code>Size</code> 完全一致</td></tr><tr><td><code>LR_IROM1.Size</code></td><td><code>0xE74C</code> = 59212</td><td><code>0x1A74</code> = 6772</td><td><strong>等于</strong> <code>Code+RO+RW</code>，也就是镜像大小</td></tr><tr><td><code>LR - ER_IROM1</code></td><td><code>0x218</code> = 536</td><td><code>0x64</code> = 100</td><td><strong>等于</strong> <code>RW-data</code>，即启动时要拷进 RAM 的 <code>.data</code></td></tr><tr><td><code>ER_RW_IRAM1.Size</code></td><td><code>0x5B60</code> = 23392</td><td><code>0x8A0</code> = 2208</td><td><strong>等于</strong> <code>RW-data + 内部 ZI</code></td></tr></tbody></table><p>四处都严丝合缝，说明 <code>Program Size</code> 与 <code>.map</code> 取自同一次构建。另外 <code>Total ROM Size</code> 是 <strong>58700</strong>（<code>0xE54C</code>），比 <code>LR_IROM1.Size</code> 少 512 字节——那 512 字节的 <code>.data</code> 初值全为 0，被归进 ZI，所以 <code>RW_IRAM1</code> 行尾是 <code>COMPRESSED[0x00000018]</code>，只有 24 字节真正需要在 Flash 里存初值。</p><h4 id="_2-4-bootloader-的关键符号与-ram-分段" tabindex="-1">2.4 Bootloader 的关键符号与 RAM 分段 <a class="header-anchor" href="#_2-4-bootloader-的关键符号与-ram-分段" aria-label="Permalink to &quot;2.4 Bootloader 的关键符号与 RAM 分段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>符号</th><th>地址</th><th>大小</th><th>所在存储</th></tr></thead><tbody><tr><td><code>s_payload</code></td><td><code>0x68000000</code></td><td>131072</td><td>外部 SRAM，IAP 载荷缓冲</td></tr><tr><td><code>s_sector_buf</code></td><td><code>0x20000980</code></td><td>4096</td><td>内部 RAM，SPI Flash 扇区缓冲</td></tr><tr><td><code>s_cache</code></td><td><code>0x20000548</code></td><td>48</td><td>内部 RAM，param 参数缓存</td></tr><tr><td><code>s_rx</code></td><td><code>0x20000508</code></td><td>48</td><td>内部 RAM，帧接收器状态</td></tr><tr><td><code>s_header</code></td><td><code>0x200004F8</code></td><td>16</td><td>内部 RAM，帧头备份</td></tr><tr><td><code>s_spi_errors</code></td><td><code>0x20000178</code></td><td>4</td><td>内部 RAM，SPI 传输错误计数</td></tr><tr><td><code>uwTick</code></td><td><code>0x20000164</code></td><td>4</td><td>内部 RAM，HAL 时基</td></tr><tr><td><code>__initial_sp</code></td><td><code>0x20005B60</code></td><td>—</td><td>内部 RAM，栈顶</td></tr></tbody></table><p><code>__initial_sp = 0x20005B60</code> 正好等于 <code>0x20000000 + 0x5B60</code>，与 <code>ER_RW_IRAM1.Size</code> 一致——栈顶落在区域末尾，是链接器布局的直接结果。</p><p><code>s_payload</code> 落在 <code>0x68000000</code> 靠的是绝对定位：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// atk-f103/Drivers/BSP/ExternalSRAM/bsp_external_sram.h</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> externalSRAM_BASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ((</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">68000000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // Bank1 NOR/SRAM3 起始地址</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> externalSRAM_SIZE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // 外部SRAM容量大小(单位为字节)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>ER_RW_IRAM1</code> 从 <code>0x20000000</code> 起连续排布，共 23392 字节。段数很多，按功能分组看更清楚：</p><table tabindex="0"><thead><tr><th>组</th><th>大小</th><th>构成</th></tr></thead><tbody><tr><td><code>.data</code> 合计</td><td>536</td><td>HAL/外设句柄、lwIP 统计量、<code>iap</code> / <code>param</code> / <code>dm9000</code> / <code>bsp_spi_flash</code> 的小状态量</td></tr><tr><td><code>.bss</code>：lwIP 协议栈</td><td>15232</td><td><code>mem.o</code> 8211（内存堆）+ <code>memp.o</code> 6689（内存池）+ <code>etharp.o</code> 240 + <code>lwip_comm.o</code> 52 + <code>ip.o</code> 24 + <code>tcp_in.o</code> 16</td></tr><tr><td><code>.bss</code>：SPI Flash 驱动</td><td>5128</td><td>扇区缓冲 4096 + 命令层静态缓冲 256 + 256 + 260 + 260</td></tr><tr><td><code>.bss</code>：串口行缓冲</td><td>472</td><td><code>usart.o</code></td></tr><tr><td><code>.bss</code>：FSMC / SPI / HAL Flash / DM9000 句柄</td><td>280</td><td><code>fsmc.o</code> 144 + <code>spi.o</code> 88 + <code>stm32f1xx_hal_flash.o</code> 32 + <code>dm9000.o</code> 16</td></tr><tr><td><code>.bss</code>：IAP 接收器</td><td>64</td><td><code>s_header</code> 16 + <code>s_rx</code> 48</td></tr><tr><td><code>.bss</code>：param 缓存</td><td>48</td><td><code>s_cache</code></td></tr><tr><td><code>.bss</code>：printf 缓冲</td><td>96</td><td><code>c_w.l(libspace.o)</code></td></tr><tr><td>HEAP + STACK</td><td>1536</td><td><code>startup_stm32f103xe.o</code>，CubeMX 默认 512 + 1024</td></tr><tr><td>—</td><td><strong>23392</strong></td><td><code>ER_RW_IRAM1.Size = 0x5B60</code></td></tr></tbody></table><p>其中 <strong>SPI Flash 驱动的 4 KB 扇区缓冲是内部 RAM 里最大的单项</strong>。它是 <code>spiflash_write()</code> 做&quot;读-改-写&quot;必需的中转：目标扇区里可能有别的数据要保留，必须先整扇区读出来再合并。省掉它的代价是每次写都要调用方自己保证扇区空白。</p><h4 id="_2-5-组件表-谁占的" tabindex="-1">2.5 组件表：谁占的 <a class="header-anchor" href="#_2-5-组件表-谁占的" aria-label="Permalink to &quot;2.5 组件表：谁占的&quot;">​</a></h4><p><code>Image component sizes</code> 按 <code>Code</code> 排前 22 名：</p><table tabindex="0"><thead><tr><th>目标文件</th><th>Code</th><th>inc.data</th><th>RO Data</th><th>RW Data</th><th>ZI Data</th></tr></thead><tbody><tr><td><code>tcp_out.o</code></td><td>8172</td><td>3702</td><td>85</td><td>0</td><td>0</td></tr><tr><td><code>tcp_in.o</code></td><td>6808</td><td>1918</td><td>0</td><td>36</td><td>16</td></tr><tr><td><code>tcp.o</code></td><td>6182</td><td>2572</td><td>201</td><td>32</td><td>0</td></tr><tr><td><code>bsp_spi_flash.o</code></td><td>4072</td><td>1658</td><td>734</td><td>4</td><td><strong>5128</strong></td></tr><tr><td><code>pbuf.o</code></td><td>2754</td><td>1328</td><td>0</td><td>1</td><td>0</td></tr><tr><td><code>etharp.o</code></td><td>2706</td><td>1000</td><td>65</td><td>1</td><td>240</td></tr><tr><td><code>mem.o</code></td><td>1912</td><td>880</td><td>0</td><td>12</td><td><strong>8211</strong></td></tr><tr><td><code>param.o</code></td><td>1732</td><td>744</td><td>167</td><td>1</td><td>48</td></tr><tr><td><code>iap.o</code></td><td>1648</td><td>636</td><td>0</td><td>4</td><td><strong>131136</strong></td></tr><tr><td><code>dm9000.o</code></td><td>1644</td><td>366</td><td>0</td><td>1</td><td>16</td></tr><tr><td><code>stm32f1xx_hal_uart.o</code></td><td>1278</td><td>10</td><td>0</td><td>0</td><td>0</td></tr><tr><td><code>stm32f1xx_hal_rcc.o</code></td><td>1240</td><td>84</td><td>18</td><td>0</td><td>0</td></tr><tr><td><code>iap_service.o</code></td><td>1122</td><td>696</td><td>172</td><td>0</td><td>0</td></tr><tr><td><code>netif.o</code></td><td>1006</td><td>392</td><td>0</td><td>12</td><td>0</td></tr><tr><td><code>ip4.o</code></td><td>938</td><td>176</td><td>0</td><td>2</td><td>0</td></tr><tr><td><code>stm32f1xx_hal_spi.o</code></td><td>910</td><td>4</td><td>0</td><td>0</td><td>0</td></tr><tr><td><code>usart.o</code></td><td>848</td><td>84</td><td>0</td><td>340</td><td>472</td></tr><tr><td><code>udp.o</code></td><td>818</td><td>324</td><td>0</td><td>8</td><td>0</td></tr><tr><td><code>icmp.o</code></td><td>816</td><td>326</td><td>0</td><td>0</td><td>0</td></tr><tr><td><code>iap_tcp.o</code></td><td>780</td><td>346</td><td>0</td><td>8</td><td>0</td></tr><tr><td><code>timeouts.o</code></td><td>704</td><td>356</td><td>16</td><td>12</td><td>0</td></tr><tr><td><code>bsp_external_sram.o</code></td><td>596</td><td>242</td><td>183</td><td>0</td><td>0</td></tr><tr><td><strong>Object Totals</strong></td><td><strong>54266</strong></td><td><strong>18876</strong></td><td><strong>2144</strong></td><td><strong>536</strong></td><td><strong>153832</strong></td></tr></tbody></table><p>三点解读：</p><p>（1）<strong>各行相加不等于 <code>Program Size</code></strong>：<code>Code</code> 合计 54266 + 库与生成项 ≈ 56472，<code>RO Data</code> 2144 + 约 60 ≈ 2204，<code>ZI Data</code> 153832 + 约 96 ≈ 153928。</p><p>（2）<strong>代码大头已经不是自己写的逻辑</strong>：lwIP 的 TCP 三件套合计 21162 字节，加上 <code>pbuf</code> / <code>etharp</code> / <code>mem</code> / <code>ip4</code> / <code>udp</code> / <code>icmp</code> / <code>netif</code>，网络栈占 Code 的一半以上；自写的 <code>iap</code> + <code>iap_tcp</code> + <code>iap_service</code> + <code>param</code> + <code>bsp_spi_flash</code> + <code>bsp_external_sram</code> 约 9950 字节。</p><p>（3）<strong><code>iap.o</code> 的 ZI 里 131072 在片外</strong>，片内只有 64 字节；<code>bsp_spi_flash.o</code> 是&quot;新代码&quot;里最占 RAM 的。</p><h4 id="_2-6-app-的镜像构成" tabindex="-1">2.6 App 的镜像构成 <a class="header-anchor" href="#_2-6-app-的镜像构成" aria-label="Permalink to &quot;2.6 App 的镜像构成&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>大小</th><th>占镜像比例</th></tr></thead><tbody><tr><td>向量表 <code>__Vectors</code>（76 个字）</td><td>304</td><td>4.5%</td></tr><tr><td>代码与其余只读常量</td><td>6368</td><td>94.0%</td></tr><tr><td><code>.data</code> 初值（启动时拷进 RAM）</td><td>100</td><td>1.5%</td></tr><tr><td><strong>合计（= bin 大小）</strong></td><td><strong>6772</strong></td><td>100%</td></tr></tbody></table><table tabindex="0"><thead><tr><th>符号</th><th>地址</th><th>大小</th></tr></thead><tbody><tr><td><code>__Vectors</code></td><td><code>0x08020000</code></td><td><code>__Vectors_Size = 0x130</code></td></tr><tr><td><code>__Vectors_End</code></td><td><code>0x08020130</code></td><td>—</td></tr><tr><td><code>Reset_Handler</code></td><td><code>0x080201DD</code></td><td>8（Thumb）</td></tr></tbody></table><p><code>0x080201DD</code> 这个值与上位机 <code>pack_iap.py</code> 打包时打印的复位向量完全一致：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>复位向量  : 0x080201DD</span></span>
<span class="line"><span>载荷 CRC32: 0x683696EE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上位机在打包前用同一套判据校验向量表（栈顶必须落在 <code>0x20000000</code> 段内、复位向量必须落在 <code>[APP_BASE, APP_END]</code> 内且 bit0 = 1），两边看到的是同一个地址——这也是 <a href="/scm-docs/sdoc/online-upgrade/iap/126b0fcbd40c60cd0540e.html">LV030-FLASH APP设计</a> 里&quot;两条都过才跳&quot;的由来。</p><p>App 的内部 RAM 只用了 2208 字节：<code>.data</code> 100（<code>main.o</code> 4 + <code>usart.o</code> 80 + <code>stm32f1xx_hal.o</code> 12 + <code>system_stm32f1xx.o</code> 4）、<code>main.o</code> 的 <code>.bss</code> 202、PAD 2、<code>usart.o</code> 的 <code>.bss</code> 272、<code>libspace.o</code> 96、HEAP 512、STACK 1024，<code>__initial_sp = 0x200008A0</code>。其中 1536 字节是 CubeMX 默认的堆栈，业务数据只占 672 字节——两个工程用的是同一份启动文件，堆栈尺寸一致。</p><h4 id="_2-7-产物文件" tabindex="-1">2.7 产物文件 <a class="header-anchor" href="#_2-7-产物文件" aria-label="Permalink to &quot;2.7 产物文件&quot;">​</a></h4><table tabindex="0"><thead><tr><th>文件</th><th>大小</th><th>说明</th></tr></thead><tbody><tr><td><code>atk-f103.axf</code></td><td>1139656</td><td>含调试信息，不能用来判断占用</td></tr><tr><td><code>atk-f103.hex</code></td><td>165148</td><td>ASCII 文本，长度与镜像无关</td></tr><tr><td><code>flash-app.axf</code></td><td>576832</td><td>同上</td></tr><tr><td><code>flash-app.hex</code></td><td>19107</td><td>同上</td></tr><tr><td><code>flash-app.bin</code></td><td><strong>6772</strong></td><td><strong>恰好等于 <code>LR_IROM1.Size</code></strong></td></tr><tr><td><code>app.img</code></td><td><strong>6796</strong></td><td>IAP 帧文件 = bin + 24 字节帧开销</td></tr></tbody></table><p><code>6796 = 6772 + 24</code> 与第 6 小节的规律一致：帧开销是定值 24 字节（16 字节头 + 8 字节尾），其余 6772 字节与将要写入 Flash 的内容逐字节相同。</p><h3 id="_3-余量总表与烧写耗时" tabindex="-1">3. 余量总表与烧写耗时 <a class="header-anchor" href="#_3-余量总表与烧写耗时" aria-label="Permalink to &quot;3. 余量总表与烧写耗时&quot;">​</a></h3><h4 id="_3-1-flash" tabindex="-1">3.1 Flash <a class="header-anchor" href="#_3-1-flash" aria-label="Permalink to &quot;3.1 Flash&quot;">​</a></h4><table tabindex="0"><thead><tr><th>区域</th><th>起始</th><th>链接上限</th><th>结束</th><th>页数</th><th>实占</th><th>占本区</th><th>余量</th></tr></thead><tbody><tr><td>第 1 块：Bootloader</td><td><code>0x08000000</code></td><td>128 KB</td><td><code>0x0801FFFF</code></td><td>64</td><td><strong>59212</strong></td><td>45.2%</td><td>71860</td></tr><tr><td>第 2 块：App</td><td><code>0x08020000</code></td><td>128 KB</td><td><code>0x0803FFFF</code></td><td>64</td><td><strong>6772</strong></td><td>5.2%</td><td>124300</td></tr><tr><td>第 3、4 块：预留</td><td><code>0x08040000</code></td><td>—</td><td><code>0x0807FFFF</code></td><td>128</td><td>0</td><td>0%</td><td>262144</td></tr><tr><td>合计</td><td><code>0x08000000</code></td><td>512 KB</td><td><code>0x0807FFFF</code></td><td>256</td><td><strong>65984</strong></td><td>12.6%</td><td>458304</td></tr></tbody></table><p>四块之间没有空隙也没有重叠，第 3、4 块整块空着。</p><p><strong>扩容临界点</strong>：Bootloader 的镜像是 59212 字节，离 128 KB 上限还有 71860 字节（约 2.2 倍的增长空间）；涨过 131072 字节，链接期就会报 <code>region overflow</code>。App 侧更宽松（余 124300 字节，约 18 倍）。</p><p>真的需要更大空间时，<strong>直接吃第 3、4 块</strong>即可：把 <code>flash-app</code> 的 <code>OCR_RVCT4</code> 大小改成 <code>0x40000</code>（256 KB）或更大，同时同步 <code>IAP_APP_END</code> 与 <code>IAP_PAYLOAD_MAX</code>。与上一版方案的关键差别在于不必再动 Bootloader 那一块——四块独立，扩容不再互相挤。</p><p>唯一要盯住的是 <code>IAP_PAYLOAD_MAX</code>：它是接收侧的溢出防线，必须与 App 区容量对齐，同时受外部 SRAM 的 1 MB 上限约束（当前载荷缓冲 128 KB，理论上最多可放大到约 900 KB）。</p><h4 id="_3-2-内部-sram" tabindex="-1">3.2 内部 SRAM <a class="header-anchor" href="#_3-2-内部-sram" aria-label="Permalink to &quot;3.2 内部 SRAM&quot;">​</a></h4><table tabindex="0"><thead><tr><th>工程</th><th>区间</th><th>容量</th><th>实占</th><th>占比</th><th>余量</th></tr></thead><tbody><tr><td>Bootloader</td><td><code>0x20000000 ~ 0x20005B5F</code></td><td>64 KB</td><td><strong>23392</strong></td><td>35.7%</td><td>42144</td></tr><tr><td>App</td><td><code>0x20000000 ~ 0x2000089F</code></td><td>64 KB</td><td><strong>2208</strong></td><td>3.4%</td><td>63328</td></tr></tbody></table><p>Bootloader 比 App 多用 21184 字节，差额几乎全部来自三处：</p><ul><li><strong>lwIP 协议栈 15380 字节</strong>——<code>mem</code> 内存堆 8211 + <code>memp</code> 内存池 6689，加上 <code>etharp</code> / <code>lwip_comm</code> / <code>ip</code> / <code>tcp_in</code> 的缓冲与统计量，以及 <code>.data</code> 里的 148 字节；</li><li><strong>SPI Flash 驱动 5132 字节</strong>——4 KB 扇区缓冲 + 命令层静态缓冲 + 错误计数；</li><li><strong>param 模块 49 字节</strong>——<code>s_cache</code> 与一个小状态量。</li></ul><p>剩下的 623 字节是 FSMC / SPI / HAL Flash / DM9000 句柄、IAP 接收器与更宽裕的串口行缓冲。内部 RAM 还剩 42 KB，是当前最宽裕的一块资源。</p><h4 id="_3-3-外部-sram" tabindex="-1">3.3 外部 SRAM <a class="header-anchor" href="#_3-3-外部-sram" aria-label="Permalink to &quot;3.3 外部 SRAM&quot;">​</a></h4><table tabindex="0"><thead><tr><th>区域</th><th>区间</th><th>大小</th><th>占比</th></tr></thead><tbody><tr><td>IAP 载荷缓冲</td><td><code>0x68000000 ~ 0x6801FFFF</code></td><td>131072</td><td>12.5%</td></tr><tr><td>未使用</td><td><code>0x68020000 ~ 0x680FFFFF</code></td><td>917504</td><td>87.5%</td></tr><tr><td>合计</td><td>—</td><td>1048576</td><td>100%</td></tr></tbody></table><p>载荷缓冲的上限 128 KB 与 App 区容量严格相等，这个&quot;巧合&quot;同样是设计出来的：<code>iap_write_appbin()</code> 的地址与长度检查要求整段落在 App 区内，所以缓冲不必更大，App 区也不必更大。反过来说，一旦把 App 区扩到 256 KB，这个缓冲也得跟着调大——它是被 <code>IAP_PAYLOAD_MAX</code> 钉住的。</p><h4 id="_3-4-烧写耗时估算" tabindex="-1">3.4 烧写耗时估算 <a class="header-anchor" href="#_3-4-烧写耗时估算" aria-label="Permalink to &quot;3.4 烧写耗时估算&quot;">​</a></h4><p>按第 9 小节的公式代入手册典型值（2 KB 页擦除约 20 ms、半字编程约 50 µs）：</p><table tabindex="0"><thead><tr><th>场景</th><th>擦除页数</th><th>编程次数</th><th>典型耗时</th><th>最坏参数下</th></tr></thead><tbody><tr><td>当前 App（6772 B）</td><td>4</td><td>3386</td><td>约 0.25 s</td><td>约 0.5 s</td></tr><tr><td>满量程（128 KB）</td><td>64</td><td>65536</td><td>约 4.6 s</td><td>约 8 s</td></tr></tbody></table><p>耗时与镜像体积基本成正比，这一点在串口升级时要有预期：满量程时串口会长时间只输出进度行（每 64 KB 一行，共 2 行）。实际耗时以串口日志为准，上表只用于估算。</p><h3 id="_4-分区是一份跨文件的约定" tabindex="-1">4. 分区是一份跨文件的约定 <a class="header-anchor" href="#_4-分区是一份跨文件的约定" aria-label="Permalink to &quot;4. 分区是一份跨文件的约定&quot;">​</a></h3><h4 id="_4-1-必须同步的六处" tabindex="-1">4.1 必须同步的六处 <a class="header-anchor" href="#_4-1-必须同步的六处" aria-label="Permalink to &quot;4.1 必须同步的六处&quot;">​</a></h4><p>分区不是只写在 <code>.uvprojx</code> 里的一串数字，而是跨多个文件的约定。任何一处单独改动都会静默出错——除了 <code>APP_BASE</code> 本身，其余几处没有任何编译期检查能发现不一致：</p><table tabindex="0"><thead><tr><th>位置</th><th>字段</th><th>当前值</th></tr></thead><tbody><tr><td><code>tools/pack_iap.py</code></td><td><code>APP_BASE</code> / <code>APP_END</code> / <code>APP_MAX_SIZE</code></td><td><code>0x08020000</code> / <code>0x0803FFFF</code> / 131072</td></tr><tr><td><code>flash-app/MDK-ARM/flash-app.uvprojx</code></td><td><code>OCR_RVCT4</code> 起始与大小</td><td><code>0x8020000</code> / <code>0x20000</code></td></tr><tr><td><code>atk-f103/MDK-ARM/atk-f103.uvprojx</code></td><td><code>OCR_RVCT4</code> 起始与大小</td><td><code>0x8000000</code> / <code>0x20000</code></td></tr><tr><td><code>atk-f103/Drivers/BSP/Iap/iap.h</code></td><td><code>IAP_APP_BASE</code> / <code>IAP_APP_END</code></td><td><code>0x08020000</code> / <code>0x08040000</code></td></tr><tr><td><code>atk-f103/Drivers/BSP/Iap/iap.h</code></td><td><code>IAP_PAYLOAD_MAX</code></td><td><code>128U * 1024U</code> = 131072</td></tr><tr><td>运行时</td><td><code>SCB-&gt;VTOR</code>（<code>iap_load_app()</code> 内赋值）</td><td><code>IAP_APP_BASE</code></td></tr><tr><td><code>flash-app/Core/Src/main.c</code></td><td><code>FLASH_APP_BASE</code>（默认值 / debug target 覆盖）</td><td><code>0x08020000</code> / <code>0x08000000</code></td></tr></tbody></table><h4 id="_4-2-三个隐性依赖" tabindex="-1">4.2 三个隐性依赖 <a class="header-anchor" href="#_4-2-三个隐性依赖" aria-label="Permalink to &quot;4.2 三个隐性依赖&quot;">​</a></h4><p>（1）<strong><code>flash-app.ioc</code> 里没有任何 IROM 配置项</strong>，App 的链接基址是纯手工设置在 <code>.uvprojx</code> 的 <code>OCR_RVCT4</code> 里。CubeMX 不会替你记住它，重新生成代码后如果发现 App 链到了 <code>0x08000000</code>，就从这张表第二行开始查。</p><p>（2）<strong><code>flash-app.uvprojx</code> 的 <code>OnChipMemories/IROM</code> 仍写着 <code>0x08000000 / 0x80000</code></strong>，那是芯片物理描述，不参与链接。查分区时不要看它。</p><p>（3）<strong><code>flash-app-debug</code> 这个 target 刻意链在 <code>0x08000000</code></strong>，用途是不经 Bootloader 直接烧进去跑。它的 <code>Define</code> 里用 <code>FLASH_APP_BASE=0x08000000</code> 覆盖默认值，所以<strong>它产出的 bin 不能拿去 IAP 升级</strong>。</p><p>上位机侧还有一层保护：<code>pack_iap.py</code> 打包前会用向量表判据校验镜像，<strong>链错基址的 App 会在上位机侧被拦下来</strong>，而不是烧进去之后再变砖。</p><h4 id="_4-3-重叠曾经是怎么发生的" tabindex="-1">4.3 重叠曾经是怎么发生的 <a class="header-anchor" href="#_4-3-重叠曾经是怎么发生的" aria-label="Permalink to &quot;4.3 重叠曾经是怎么发生的&quot;">​</a></h4><p>两个工程最初都保留 CubeMX 的默认值——IROM1 = <code>0x08000000 / 0x80000</code>（整片 512 KB）。早期把 App 基址改到 <code>0x08010000</code> 之后，两者就重叠了 448 KB：</p><p><img src="`+n+'" alt="Bootloader 与 App 的 IROM 声明范围重叠"></p><p><strong>链接器不会报错</strong>，因为 Bootloader 实际只用了 12 KB，离它自己声明的 512 KB 上限还远得很。隐患被&quot;暂时安全&quot;掩盖住了。现在的四块划分从根上解决了这件事——每块都有明确的主人、明确的上限，谁都不声明别人的地址。</p><p>但&quot;上限被收紧&quot;并不等于&quot;永远不会越界&quot;：真正的危险变成了&quot;为了让某个工程过编译，顺手把它的 <code>OCR_RVCT4</code> 改大&quot;。</p><h4 id="_4-4-越界之后会发生什么" tabindex="-1">4.4 越界之后会发生什么 <a class="header-anchor" href="#_4-4-越界之后会发生什么" aria-label="Permalink to &quot;4.4 越界之后会发生什么&quot;">​</a></h4><p>如果 Bootloader 某次改动涨过 128 KB，链接期会直接拦下（这是我们要的效果）。但如果为了让它过编译而把 <code>atk-f103.uvprojx</code> 的上限改成比如 <code>0x40000</code>，它就会长进 App 区，然后在<strong>下一次升级时</strong>出问题：</p><p>（1）<code>iap_write_appbin()</code> 擦除 <code>0x08020000</code> 起的若干页；</p><p>（2）这些页里已经有 Bootloader 自己的代码（因为它越过了 128 KB 边界）；</p><p>（3）接收与跳转代码被抹掉，串口从此再也无法收帧。</p><p>这个故障的恶劣之处在于它<strong>不可远程恢复</strong>——设备已经听不到任何指令，只能靠 JTAG 或 ISP 重新烧 Bootloader。App 侧越界没有这么致命（只会踩掉第 3 块的数据），但同样属于&quot;分区约定被破坏&quot;，会让后续扩容计划失效。</p><h4 id="_4-5-现在的防线" tabindex="-1">4.5 现在的防线 <a class="header-anchor" href="#_4-5-现在的防线" aria-label="Permalink to &quot;4.5 现在的防线&quot;">​</a></h4><p>把 <code>atk-f103.uvprojx</code> 的 <code>OCR_RVCT4</code> 大小设成 <code>0x20000</code> 之后，风险从&quot;运行时静默踩内存&quot;变成&quot;链接期当场报错&quot;：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: L6220E: Execution Region ER_IROM1 size (0x...) exceeds maximum size (0x20000).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>验证方法与第 7.3 小节相同：临时把 <code>Size</code> 改成明显偏小的值（比如 <code>0x4000</code>），全量重建，应当看到上面这行报错；改回 <code>0x20000</code> 重新构建即恢复。</p><h2 id="四、-复核-拿到属于你这个版本的数字" tabindex="-1">四、 复核：拿到属于你这个版本的数字 <a class="header-anchor" href="#四、-复核-拿到属于你这个版本的数字" aria-label="Permalink to &quot;四、 复核：拿到属于你这个版本的数字&quot;">​</a></h2><p>数据会过期，方法是固定的。任何时候需要重新判断&quot;还剩多少&quot;，按这五步走一遍：</p><table tabindex="0"><thead><tr><th>步骤</th><th>动作</th><th>看什么</th></tr></thead><tbody><tr><td>1</td><td>全量重建（<code>UV4 -r</code>，不是增量 <code>-b</code>）</td><td>确保 <code>.map</code> 与产物同源</td></tr><tr><td>2</td><td>读编译输出的 <code>Program Size</code></td><td>套第 3 小节的加权和，得到 Flash 与 RAM</td></tr><tr><td>3</td><td>打开 <code>.map</code> 查 <code>LR_IROM1</code> / <code>ER_RW_IRAM1</code> 行</td><td><code>Size</code> 与 <code>Max</code>，核对第 5.2 小节的四处对应</td></tr><tr><td>4</td><td>查 <code>OCR_RVCT4</code> 或 <code>.ld</code> 的 <code>LENGTH</code></td><td>确认分区上限没变过（这一步最容易被跳过）</td></tr><tr><td>5</td><td>算余量与临界增量</td><td>与第 8.3 小节的经验线比，判断是否需要扩容</td></tr></tbody></table><p>三条使用提醒：</p><p>（1）<strong>不要用 <code>.axf</code> 或 <code>.hex</code> 的大小判断占用</strong>。前者含调试信息（本工程 1.1 MB），后者是 ASCII 文本（161 KB），都与镜像无关。唯一可信的是 <code>Program Size</code> 的 <code>Code+RO-data+RW-data</code>，以及 <code>.map</code> 里 <code>LR_IROM1.Size</code>。</p><p>（2）<strong><code>Program Size</code> 与 <code>.map</code> 必须来自同一次构建</strong>。增量构建只改了部分文件时，两者可能对不上；核对前先做一次全量重建。</p><p>（3）<strong><code>ZI-data</code> 不等于内部 RAM 占用</strong>。本工程 Bootloader 的 153928 字节里有 131072 字节在片外 SRAM，看这一项时务必结合 <code>ER_RW_IRAM1.Size</code>。</p><p>只要这五步还能走通，本文的数字过期与否都不影响你得出当前版本的结论——<strong>方法留下来，数字随时重算</strong>。</p>',191)])])}const x=d(r,[["render",l]]);export{u as __pageData,x as default};
